std::string replace_linear(const std::string& source,const std::string& old,const std::string& replacement){std::string result;result.reserve(source.size());std::size_t begin=0,pos=source.find(old);while(pos!=std::string::npos){result.append(source,begin,pos-begin);result.append(replacement);begin=pos+old.size();pos=source.find(old,begin);}result.append(source,begin,std::string::npos);return result;}
